(3515157, 490024, 35895, '<td valign="top">very nice :)</td>', 'very nice :)', '2007-04-03 16:17:07.000000', NULL, 1),
(3515164, 488948, 32378, '<td valign="top">Good shot, good job with depth of field.  Too bad he wasn''t flying toward you when you snapped this.</td>', 'Good shot, good job with depth of field.  Too bad he wasn''t flying toward you when you snapped this.', '2007-04-03 16:20:25.000000', NULL, 1),
