(3523021, 489181, 3032, '<td valign="top">Great expression. Good.</td>', 'Great expression. Good.', '2007-04-05 17:38:39.000000', NULL, 1),
(3523024, 491130, 3032, '<td valign="top">I do not like these colors. The light in the tower is cool, the sky is ok, but the blue of the water is too much.</td>', 'I do not like these colors. The light in the tower is cool, the sky is ok, but the blue of the water is too much.', '2007-04-05 17:40:18.000000', NULL, 1);
