(3523229, 491043, 57032, '<td valign="top">I liked the photo, but the blurring seemed a bit messy to me. For example, a bit of the blur was caught on the chair, which was predominantly in focus.  Could be just me, though.</td>', 'I liked the photo, but the blurring seemed a bit messy to me. For example, a bit of the blur was caught on the chair, which was predominantly in focus.  Could be just me, though.', '2007-04-05 18:40:28.000000', NULL, 1),
(3523233, 490824, 57032, '<td valign="top">Too much detail is lost in the drums on the left for me.</td>', 'Too much detail is lost in the drums on the left for me.', '2007-04-05 18:41:03.000000', NULL, 1),
(3523235, 490919, 57032, '<td valign="top">Would''ve been a great shot at sunset.</td>', 'Would''ve been a great shot at sunset.', '2007-04-05 18:41:35.000000', NULL, 1),
