(3527911, 487101, 61651, '<td valign="top">Nicely composed in the frame, makes you stop and look.  I like how the Chaplin face is more or less level in the image, but is offset by the slight diagonal created by the door frames.</td>', 'Nicely composed in the frame, makes you stop and look.  I like how the Chaplin face is more or less level in the image, but is offset by the slight diagonal created by the door frames.', '2007-04-07 16:02:39.000000', NULL, 1),
(3527914, 479058, 50695, '<td valign="top">I feel like I''m on my knees with you. 7 bump to 8</td>', 'I feel like I''m on my knees with you. 7 bump to 8', '2007-04-07 16:03:04.000000', NULL, 1),
(3527915, 490814, 50695, '<td valign="top">nice harsh minimalism. 7 bump to 8</td>', 'nice harsh minimalism. 7 bump to 8', '2007-04-07 16:03:16.000000', NULL, 1),
