(3527923, 490859, 50695, '<td valign="top">8 for a great title.</td>', '8 for a great title.', '2007-04-07 16:07:11.000000', NULL, 1),
(3527927, 486194, 61651, '<td valign="top">You did a very nice job here and I like the composition, but personally I''d prefer to see the feet and hands in sharper focus.</td>', 'You did a very nice job here and I like the composition, but personally I''d prefer to see the feet and hands in sharper focus.', '2007-04-07 16:09:05.000000', NULL, 1),
(3527928, 478695, 50695, '<td valign="top">not the most original shot, but perfectly executed. the lines and composition are excellent. 8</td>', 'not the most original shot, but perfectly executed. the lines and composition are excellent. 8', '2007-04-07 16:09:16.000000', NULL, 1),
(3527930, 491157, 50695, '<td valign="top">fascinating tableau. 7</td>', 'fascinating tableau. 7', '2007-04-07 16:09:38.000000', NULL, 1),
